import itertools
import random

def get_girth(n, edges):
    """Compute the girth of a graph with n vertices and given edges."""
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # BFS from each vertex to find shortest cycle
    min_cycle = float('inf')

    for start in range(n):
        # BFS to find shortest cycle through start
        visited = {start: 0}
        queue = [(start, -1, 0)]  # (current, parent, depth)

        while queue:
            curr, parent, depth = queue.pop(0)
            if depth >= min_cycle // 2:
                break
            for neighbor in adj[curr]:
                if neighbor == parent:
                    continue
                if neighbor in visited:
                    # Found a cycle
                    cycle_len = depth + visited[neighbor] + 1
                    min_cycle = min(min_cycle, cycle_len)
                else:
                    visited[neighbor] = depth + 1
                    queue.append((neighbor, curr, depth + 1))

    return min_cycle if min_cycle != float('inf') else 0

def is_3_colorable(n, edges):
    """Check if graph is 3-colorable using backtracking."""
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    colors = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        for c in range(3):
            valid = True
            for neighbor in adj[v]:
                if colors[neighbor] == c:
                    valid = False
                    break
            if valid:
                colors[v] = c
                if backtrack(v + 1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

